    font-size: .9rem;
    font-weight: 500;
    color: var(--muted);
    background: transparent;
    border: 1px solid var(--border);
    border-radius: 8px;
    cursor: pointer;
    transition: all .15s;
  }
  .filter-btn:hover { color: var(--text); }
  .filter-btn.active {
    color: #fff;
